public sealed class EmailWorker(EmailQueue q, IServiceScopeFactory scopes,
    ILogger<EmailWorker> log) : BackgroundService
{
    protected override async Task ExecuteAsync(CancellationToken stoppingToken)
    {
        await foreach (var to in q.ReadAllAsync(stoppingToken))
        {
            await using var scope = scopes.CreateAsyncScope();   // its own DbContext per email
            var sender = scope.ServiceProvider.GetRequiredService<IEmailSender>();
            try { await sender.SendAsync(to, stoppingToken); }
            catch (Exception e) when (e is not OperationCanceledException)
            { log.LogError(e, "Email to {To} not sent", to); }
        }
    }
}

builder.Services.AddSingleton<EmailQueue>();
builder.Services.AddHostedService<EmailWorker>();
